import{_ as o,o as d,c as a,a2 as e}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"第 1 课：AI 编程助手是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-1/lesson-1.md","filePath":"modules/module-1/lesson-1.md"}'),r={name:"modules/module-1/lesson-1.md"};function l(i,t,s,n,h,p){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="第-1-课-ai-编程助手是什么" tabindex="-1">第 1 课：AI 编程助手是什么？ <a class="header-anchor" href="#第-1-课-ai-编程助手是什么" aria-label="Permalink to &quot;第 1 课：AI 编程助手是什么？&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：理解 AI 编程助手的基本概念，知道 Codex 和传统聊天机器人的区别<br> ⏱️ <strong>预计时长</strong>：15 分钟<br> 🎯 <strong>本节节奏</strong>：先演示 → 后讲解 → 再实操</p></blockquote><hr><h2 id="一、先演示-让-ai-帮你做件事" tabindex="-1">一、先演示：让 AI 帮你做件事 <a class="header-anchor" href="#一、先演示-让-ai-帮你做件事" aria-label="Permalink to &quot;一、先演示：让 AI 帮你做件事&quot;">​</a></h2><p>在开始之前，我想让你先体验一下&quot;AI 帮你干活&quot;的感觉。</p><p>打开 ChatGPT（或任何 AI 聊天工具），输入下面这句话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个 Python 脚本，读取当前文件夹下所有 .txt 文件，统计每个文件的行数，最后输出一个汇总报告。</span></span></code></pre></div><p>看看 AI 是怎么回答的——它通常会直接给你一段可运行的代码。你复制这段代码，保存为 <code>count_lines.py</code>，然后在终端运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> count_lines.py</span></span></code></pre></div><p>恭喜你，你已经用 AI 完成了一个小工具的开发。<strong>你没有写过一行代码，但你让它帮你写了。</strong></p><p>这就是 AI 编程助手的威力。</p><hr><h2 id="二、从-聊天机器人-到-能帮你干活的智能体" tabindex="-1">二、从&quot;聊天机器人&quot;到&quot;能帮你干活的智能体&quot; <a class="header-anchor" href="#二、从-聊天机器人-到-能帮你干活的智能体" aria-label="Permalink to &quot;二、从&quot;聊天机器人&quot;到&quot;能帮你干活的智能体&quot;&quot;">​</a></h2><h3 id="_2-1-聊天机器人-vs-编程助手" tabindex="-1">2.1 聊天机器人 vs 编程助手 <a class="header-anchor" href="#_2-1-聊天机器人-vs-编程助手" aria-label="Permalink to &quot;2.1 聊天机器人 vs 编程助手&quot;">​</a></h3><p>你可能用过 ChatGPT、文心一言、通义千问这类 AI 工具。它们有一个共同特点：<strong>只能和你聊天</strong>。</p><p>你问它问题，它给你文字回复。你可以让它写代码片段，但代码能不能跑、怎么跑、在哪里跑——它不管。</p><p><strong>AI 编程助手（比如 Codex）不一样。</strong> 它不仅&quot;能聊&quot;，还能&quot;能干&quot;：</p><table tabindex="0"><thead><tr><th>能力</th><th>聊天机器人</th><th>AI 编程助手（Codex）</th></tr></thead><tbody><tr><td>回答问题</td><td>✅</td><td>✅</td></tr><tr><td>写代码片段</td><td>✅</td><td>✅</td></tr><tr><td>读你的项目文件</td><td>❌</td><td>✅</td></tr><tr><td>运行代码并调试</td><td>❌</td><td>✅</td></tr><tr><td>操作电脑上的文件</td><td>❌</td><td>✅</td></tr><tr><td>调用外部工具</td><td>❌</td><td>✅</td></tr><tr><td>完成完整任务</td><td>❌</td><td>✅</td></tr></tbody></table><h3 id="_2-2-codex-到底是什么" tabindex="-1">2.2 Codex 到底是什么？ <a class="header-anchor" href="#_2-2-codex-到底是什么" aria-label="Permalink to &quot;2.2 Codex 到底是什么？&quot;">​</a></h3><p><strong>Codex 是 OpenAI 推出的 AI 编程智能体（coding agent）。</strong></p><p>注意两个关键词：</p><ul><li><strong>编程</strong>：它的核心能力围绕代码展开——写代码、改代码、调试代码、解释代码</li><li><strong>智能体（Agent）</strong>：它不是被动回答问题的工具，而是能主动执行任务的&quot;助手&quot;</li></ul><p>你可以把 Codex 想象成一个<strong>会编程的实习生</strong>：</p><ul><li>你告诉它要做什么（用自然语言）</li><li>它自己去读相关文件、写代码、运行测试、发现问题、修正错误</li><li>最后把成果交给你</li></ul><p><strong>你不需要教它编程知识，你只需要告诉它你要什么。</strong></p><hr><h2 id="三、生活中的类比" tabindex="-1">三、生活中的类比 <a class="header-anchor" href="#三、生活中的类比" aria-label="Permalink to &quot;三、生活中的类比&quot;">​</a></h2><p>如果还是觉得抽象，我们用几个生活场景来理解：</p><h3 id="类比-1-codex-会编程的实习生" tabindex="-1">类比 1：Codex = 会编程的实习生 <a class="header-anchor" href="#类比-1-codex-会编程的实习生" aria-label="Permalink to &quot;类比 1：Codex = 会编程的实习生&quot;">​</a></h3><p>你是一家公司的新人主管，招了一个实习生。这个实习生：</p><ul><li>会写代码</li><li>能读你给的文件</li><li>能自己想办法解决问题</li><li>做错了你会告诉他，他会改</li><li>做完会把成果交给你审核</li></ul><p><strong>Codex 就是这个实习生。</strong> 你不需要会编程，你只需要像主管一样&quot;提需求&quot;。</p><h3 id="类比-2-codex-万能秘书" tabindex="-1">类比 2：Codex = 万能秘书 <a class="header-anchor" href="#类比-2-codex-万能秘书" aria-label="Permalink to &quot;类比 2：Codex = 万能秘书&quot;">​</a></h3><p>你的秘书能帮你：</p><ul><li>整理文件（按类型、日期分类）</li><li>搜索资料（上网查资料并整理成报告）</li><li>写邮件（根据你给的要点自动生成）</li><li>做表格（你说数据格式，她帮你排版）</li></ul><p><strong>Codex 就是这个秘书，只不过它额外还会写代码。</strong></p><h3 id="类比-3-codex-乐高积木-说明书" tabindex="-1">类比 3：Codex = 乐高积木 + 说明书 <a class="header-anchor" href="#类比-3-codex-乐高积木-说明书" aria-label="Permalink to &quot;类比 3：Codex = 乐高积木 + 说明书&quot;">​</a></h3><p>假设你想搭一个乐高城堡：</p><ul><li><strong>传统方式</strong>：你自己一块一块拼，需要看懂说明书</li><li><strong>Codex 方式</strong>：你告诉它&quot;我要一个带塔楼和城墙的城堡&quot;，它帮你拼好，你只管验收</li></ul><hr><h2 id="四、codex-不是代码补全工具" tabindex="-1">四、Codex 不是代码补全工具 <a class="header-anchor" href="#四、codex-不是代码补全工具" aria-label="Permalink to &quot;四、Codex 不是代码补全工具&quot;">​</a></h2><p>很多人第一次听说 AI 编程工具，想到的是 GitHub Copilot。Copilot 是什么？它是一个<strong>代码补全工具</strong>——你在编辑器里打字，它帮你补全下一行代码。</p><p><strong>Codex 比 Copilot 强大得多。</strong></p><table tabindex="0"><thead><tr><th>对比项</th><th>GitHub Copilot</th><th>Codex</th></tr></thead><tbody><tr><td>工作位置</td><td>编辑器内</td><td>独立应用/命令行</td></tr><tr><td>能力范围</td><td>补全代码</td><td>读项目、写代码、运行命令、调工具</td></tr><tr><td>任务粒度</td><td>单行/单函数</td><td>完整功能/完整项目</td></tr><tr><td>是否需要编程基础</td><td>需要（至少看得懂代码）</td><td>不需要（用自然语言对话）</td></tr><tr><td>典型用户</td><td>程序员</td><td>任何人（包括不会编程的人）</td></tr></tbody></table><p><strong>简单说：Copilot 是给程序员用的&quot;辅助轮&quot;，Codex 是给普通人用的&quot;自动驾驶&quot;。</strong></p><hr><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>AI 编程助手 vs 聊天机器人</td><td>前者能干活，后者只能聊天</td></tr><tr><td>Codex 的核心定位</td><td>OpenAI 的 AI 编程智能体，能读文件、写代码、运行命令</td></tr><tr><td>Codex vs Copilot</td><td>Copilot 补全代码，Codex 完成任务</td></tr><tr><td>类比理解</td><td>Codex = 会编程的实习生 / 万能秘书</td></tr></tbody></table><hr><h2 id="六、课后思考" tabindex="-1">六、课后思考 <a class="header-anchor" href="#六、课后思考" aria-label="Permalink to &quot;六、课后思考&quot;">​</a></h2><ol><li>你工作中有没有那种&quot;重复做、很烦人、但又不得不做&quot;的任务？想想看，Codex 能不能帮你做？</li><li>你觉得&quot;会编程&quot;和&quot;能用 AI 编程&quot;之间有什么区别？</li></ol><blockquote><p>💡 提示：下一节课我们会展示 Codex 具体能帮你做什么，到时候你可能会发现更多可以用它替代的任务。</p></blockquote><hr><h2 id="七、下一步" tabindex="-1">七、下一步 <a class="header-anchor" href="#七、下一步" aria-label="Permalink to &quot;七、下一步&quot;">​</a></h2><p><a href="./lesson-2.html">→ 第 2 课：Codex 能帮你做什么？</a></p>',55)])])}const b=o(r,[["render",l]]);export{c as __pageData,b as default};
